from solution import OrphanGuard

def test_no_orphans():
    g = OrphanGuard([(101, 100), (102, 100), (100, -1)])
    return str(sorted(g.check_orphans()))

def test_one_orphan():
    g = OrphanGuard([(201, 200), (202, 201), (200, -1)])
    return str(sorted(g.check_orphans()))

def test_orphan_without_parent_in_table():
    g = OrphanGuard([(301, 300), (302, 999)])
    return str(sorted(g.check_orphans()))

def test_no_entries():
    g = OrphanGuard([])
    return str(sorted(g.check_orphans()))

def test_orphan_chain():
    g = OrphanGuard([(401, 400), (400, -1)])
    return str(sorted(g.check_orphans()))
